$ErrorActionPreference='Stop';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false);$ports=@(Get-CimInstance Win32_SerialPort|Select DeviceID,PNPDeviceID);$parents=@();foreach($p in $ports){if($p.DeviceID -eq 'COM5'){$parents+=Get-PnpDeviceProperty -InstanceId $p.PNPDeviceID -KeyName DEVPKEY_Device_Parent|Select InstanceId,Data}};[pscustomobject]@{Power=@(Get-CimInstance -Namespace root/wmi -ClassName BatteryStatus|Select PowerOnline,Discharging,Charging);Temp=$env:TEMP;Ports=$ports;Parents=$parents}|ConvertTo-Json -Depth 6